const webhookItem = $('Webhook1').first()?.json ?? {};
const payload = webhookItem.body ?? webhookItem;
const event = String(payload?.event || '').toLowerCase();

if (event !== 'seeker_resume_uploaded') {
  return [];
}

const MIN_RECOMMENDATION_SCORE = 50;

const seekerEmail = String(payload.email || '').trim();
if (!seekerEmail) {
  throw new Error('Missing seeker email in payload');
}

const seekerUserId = Number(payload.user_id || 0);
if (!Number.isFinite(seekerUserId) || seekerUserId <= 0) {
  throw new Error('Missing or invalid user_id in payload');
}

const seekerName = String(payload.name || 'Jobseeker').trim();
const resumeText = String(payload.resume_text || '').toLowerCase();
const seekerEducationRaw = String(payload.educational_attainment || '').trim();

let seekerSkills = payload.parsed_skill ?? [];
if (typeof seekerSkills === 'string') {
  try {
    seekerSkills = JSON.parse(seekerSkills);
  } catch {
    seekerSkills = [seekerSkills];
  }
}
if (!Array.isArray(seekerSkills) && typeof seekerSkills === 'object' && seekerSkills !== null) {
  seekerSkills = Object.values(seekerSkills);
}
seekerSkills = seekerSkills.map((s) => String(s).toLowerCase().trim()).filter(Boolean);

const normalizeText = (value) => String(value || '').toLowerCase().trim();
const normalizeNoSymbols = (value) => normalizeText(value).replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

const educationLevels = [
  { level: 'doctorate', rank: 5, keywords: ['doctorate', 'doctoral', 'phd', 'doctor of philosophy'] },
  { level: 'masters', rank: 4, keywords: ['master', 'masters', "master's", 'm.s', 'ms', 'm.a', 'ma', 'mba'] },
  { level: 'bachelors', rank: 3, keywords: ['bachelor', 'bachelors', "bachelor's", 'b.s', 'bs', 'b.a', 'ba', 'college graduate', 'college grad', 'degree'] },
  { level: 'associate', rank: 2, keywords: ['associate degree', 'associate'] },
  { level: 'vocational', rank: 2, keywords: ['vocational', 'tesda', 'certificate', 'technical-vocational', 'nc ii', 'nc iii'] },
  { level: 'highschool', rank: 1, keywords: ['high school', 'secondary', 'senior high', 'shs'] },
];

const inferEducationLevel = (value) => {
  const normalized = normalizeNoSymbols(value);
  if (!normalized || ['any', 'not specified', 'none', 'n a', 'na'].includes(normalized)) {
    return null;
  }

  for (const item of educationLevels) {
    if (item.keywords.some((keyword) => normalized.includes(normalizeNoSymbols(keyword)))) {
      return item.level;
    }
  }

  return null;
};

const levelRank = (level) => {
  const found = educationLevels.find((item) => item.level === level);
  return found ? found.rank : null;
};

let seekerEducationLevel = inferEducationLevel(seekerEducationRaw);
if (!seekerEducationLevel) {
  seekerEducationLevel = inferEducationLevel(resumeText);
}

const jobs = $input.all().map((item) => item.json);
const scored = [];
const disqualified = [];
const allMatches = [];

for (const job of jobs) {
  const title = String(job.title || '');
  const company = String(job.company || '');
  const location = String(job.location || '');
  const requiredEducationRaw = String(job.educational_attainment_required || '').trim();

  const requiredEducationLevel = inferEducationLevel(requiredEducationRaw);
  const isEducationRequired = (() => {
    const normalized = normalizeText(requiredEducationRaw);
    return normalized !== '' && !['any', 'not specified', 'none', 'n/a', 'na'].includes(normalized);
  })();

  if (isEducationRequired) {
    let educationQualified = false;

    if (requiredEducationLevel && seekerEducationLevel) {
      educationQualified = Number(levelRank(seekerEducationLevel) || 0) >= Number(levelRank(requiredEducationLevel) || 0);
    } else {
      const seekerNormalized = normalizeNoSymbols(seekerEducationRaw);
      const requiredNormalized = normalizeNoSymbols(requiredEducationRaw);
      educationQualified = seekerNormalized !== '' && (
        seekerNormalized === requiredNormalized ||
        seekerNormalized.includes(requiredNormalized)
      );
    }

    if (!educationQualified) {
      const seekerEducationLabel = seekerEducationRaw || 'Not specified';
      const reason = `Auto-disqualified: requires ${requiredEducationRaw}, applicant has ${seekerEducationLabel}.`;

      const disqualifiedItem = {
        job_id: Number(job.id),
        title,
        company,
        location,
        score: 0,
        reasons: reason,
        disqualified: true
      };

      disqualified.push(disqualifiedItem);
      allMatches.push(disqualifiedItem);
      continue;
    }
  }

  let requiredSkills = job.required_skills ?? [];
  if (typeof requiredSkills === 'string') {
    try {
      requiredSkills = JSON.parse(requiredSkills);
    } catch {
      requiredSkills = [requiredSkills];
    }
  }
  if (!Array.isArray(requiredSkills) && typeof requiredSkills === 'object' && requiredSkills !== null) {
    requiredSkills = Object.values(requiredSkills);
  }
  requiredSkills = requiredSkills.map((s) => String(s).toLowerCase().trim()).filter(Boolean);

  let score = 0;
  const reasons = [];

  let skillHits = 0;
  for (const skill of requiredSkills) {
    if (seekerSkills.includes(skill) || resumeText.includes(skill)) {
      skillHits++;
    }
  }

  if (requiredSkills.length > 0) {
    const skillScore = (skillHits / requiredSkills.length) * 70;
    score += skillScore;
    if (skillHits > 0) {
      reasons.push(`${skillHits}/${requiredSkills.length} required skills matched`);
    }
  }

  const titleKeywords = title.toLowerCase().split(/\s+/).filter((w) => w.length > 3);
  const titleHits = titleKeywords.filter((k) => resumeText.includes(k)).length;
  if (titleKeywords.length > 0) {
    const titleScore = (titleHits / titleKeywords.length) * 30;
    score += titleScore;
    if (titleHits > 0) {
      reasons.push(`title alignment (${titleHits} keyword hit/s)`);
    }
  }

  const finalScore = Math.round(Math.min(score, 100));

  const matchItem = {
    job_id: Number(job.id),
    title,
    company,
    location,
    score: finalScore,
    reasons: reasons.join(' | ') || 'General profile fit',
    disqualified: false
  };

  allMatches.push(matchItem);

  if (finalScore >= MIN_RECOMMENDATION_SCORE) {
    scored.push(matchItem);
  }
}

scored.sort((a, b) => Number(b.score) - Number(a.score));
const top = scored.slice(0, 5);

if (allMatches.length === 0) {
  return [];
}

const recommendationListHtml = top.length > 0
  ? '<ul>' + top.map((r) => '<li><b>' + r.title + '</b> - ' + r.company + ' (' + r.location + ') <b>' + r.score + '%</b><br/><small>' + r.reasons + '</small></li>').join('') + '</ul>'
  : '<p>No jobs passed resume-fit screening at the moment.</p>';

const disqualifiedListHtml = disqualified.length > 0
  ? '<br/><p><b>Not qualified due to education requirement:</b></p><ul>' + disqualified.map((r) => '<li><b>' + r.title + '</b> - requires higher educational attainment.<br/><small>' + r.reasons + '</small></li>').join('') + '</ul>'
  : '';

let emailSubject = 'Your CityJobLink screening results';
if (top.length === 0 && disqualified.length > 0) {
  emailSubject = 'Not Qualified for Current Open Jobs';
}

const emailHtml = `Hi ${seekerName},<br/><br/>${top.length > 0 ? 'Here are your top recommended jobs based on your resume:' : 'We screened current openings using your resume.'}<br/><br/>${recommendationListHtml}${disqualifiedListHtml}<br/><br/>Log in to CityJobLink to view details and apply to qualified jobs.<br/><br/>Best regards,<br/>CityJobLink Team`;

return [{
  json: {
    event: 'seeker_resume_uploaded',
    seeker_user_id: seekerUserId,
    to_email: seekerEmail,
    seeker_name: seekerName,
    recommendations: top,
    disqualified_jobs: disqualified,
    all_matches: allMatches,
    email_subject: emailSubject,
    email_html: emailHtml
  }
}];

const payload = $json;
const seekerUserId = Number(payload.seeker_user_id || 0);
if (!Number.isFinite(seekerUserId) || seekerUserId <= 0) {
  return [];
}

const matches = Array.isArray(payload.all_matches) ? payload.all_matches : [];

return matches.map((match) => ({
  json: {
    job_id: Number(match.job_id),
    user_id: seekerUserId,
    match_score: Number(match.score || 0),
    match_reasons: String(match.reasons || '')
  }
}));

const payload = $input.first()?.json ?? {};
const recommendations = Array.isArray(payload.recommendations) ? payload.recommendations : [];
return recommendations.length > 0 ? [{ json: payload }] : [];
